class ReplyKeyboard:
    def __init__(self):
        self.rows = []

    def row(self, *buttons):
        self.rows.append([{"text": b} for b in buttons])
        return self

    def build(self):
        return {"keyboard": self.rows, "resize_keyboard": True}

    @staticmethod
    def remove():
        return {"remove_keyboard": True}


class InlineKeyboard:
    def __init__(self):
        self.keyboard = []
        self.current_row = []

    def _create_button(self, text, val):
        if val.startswith("http"):
            return {"text": text, "url": val}
        return {"text": text, "callback_data": val}

    def add_to_row(self, text, val):
        self.current_row.append(self._create_button(text, val))
        return self

    def row(self, text, val):
        if self.current_row:
            self.keyboard.append(self.current_row)
            self.current_row = []

        self.keyboard.append([self._create_button(text, val)])
        return self

    def build(self):
        if self.current_row:
            self.keyboard.append(self.current_row)
            self.current_row = []

        return {"inline_keyboard": self.keyboard}
